-- CLAUDE-315: same end schema as
-- `../sqlite/0022_claude_invocations.sql`, spelled per the CLAUDE-250 squash
-- mapping (`BIGINT` for every integer, `DOUBLE PRECISION` for `REAL`,
-- `GENERATED BY DEFAULT AS IDENTITY` for the autoincrement key).

CREATE TABLE IF NOT EXISTS claude_invocations (
    id                        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ts                        TEXT NOT NULL,
    action                    TEXT NOT NULL,
    job_key                   TEXT,
    run_id                    BIGINT REFERENCES runs(id),
    exit_code                 BIGINT,
    timed_out                 BIGINT NOT NULL,
    ok                        BIGINT NOT NULL,
    cost_usd                  DOUBLE PRECISION NOT NULL,
    total_tokens              BIGINT NOT NULL,
    rate_limit_status         TEXT,
    rate_limit_type           TEXT,
    five_hour_utilization     DOUBLE PRECISION,
    five_hour_resets_at       TEXT,
    seven_day_utilization     DOUBLE PRECISION,
    seven_day_resets_at       TEXT,
    max_five_hour_utilization DOUBLE PRECISION,
    max_seven_day_utilization DOUBLE PRECISION,
    overage_status            TEXT,
    is_using_overage          BIGINT,
    api_retries_json          TEXT,
    stream_log_path           TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_claude_invocations_ts ON claude_invocations(ts);
